function demo() {
  console.log(a); // undefined (hoisted)
  // console.log(b); // ReferenceError (TDZ)

  var a = 1;
  let b = 2;
  const c = [1, 2];

  if (true) {
    var a = 10;   // same variable — function scope
    let b = 20;   // new variable — block scope
  }

  c.push(3);      // allowed: mutation ≠ reassignment
  // c = [9];     // TypeError: assignment to constant
}
demo();
console.log(a); // 10 — var leaked out of the block

typeof null;        // 'object' (historical bug)
typeof function(){}; // 'function'
0.1 + 0.2;          // 0.30000000000000004

let a = { n: 1 };
let b = a;
b.n = 2;
console.log(a.n);   // 2 — same object, copied reference

sayHi();            // works — full function declaration hoisted
function sayHi() { console.log('hi'); }

console.log(x);     // undefined — var hoisted & initialized
var x = 5;

// console.log(y);  // ReferenceError — TDZ
let y = 10;
